#!/usr/bin/env bash
# shellcheck source-path=SCRIPTDIR
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill; its library is scripts/lib/wizard.sh.

set -euo pipefail

# shellcheck source=lib/wizard.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/wizard.sh"
# shellcheck source=lib/aws-wizard.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/aws-wizard.sh"

# ──────────────────────────────────────────────────────────────────────────
# STAGES: one stage() per step the human takes. TOTAL_STAGES matches them.
# ──────────────────────────────────────────────────────────────────────────

# What remains after the first deploy (ticket #96, spec #87), once
# scripts/aws-first-deploy-wizard.sh has run: the SNS e-mail subscription
# confirmed, a manual run of both maintenance tasks, the plantai.ia.br domain
# verified in Resend (records on the send. subdomain, in Registro.br) and the
# production EMAIL_FROM switched to PlantAí <nao-responda@plantai.ia.br>,
# ending with a real sign-up whose code arrives from that address.
#
# No secret is written to disk, to argv or to the shell history: values are
# typed hidden (read -s) and reach the AWS CLI and curl through stdin. Every
# stage checks the current state first, so a re-run skips what is done.
#
# Usage: scripts/aws-after-first-deploy-wizard.sh   (AWS_PROFILE is honored)

EMAIL_FROM_PRODUCTION="PlantAí <nao-responda@plantai.ia.br>"

WORK_DIR=$(mktemp -d)
chmod 700 "$WORK_DIR"
trap 'rm -rf "$WORK_DIR"' EXIT

# subscription_state TOPIC: "<SubscriptionArn> <Endpoint>" of the topic's
# e-mail subscription (SubscriptionArn is PendingConfirmation until clicked).
subscription_state() {
  aws sns list-subscriptions-by-topic --topic-arn "$1" \
    --query "Subscriptions[?Protocol=='email'] | [0].[SubscriptionArn,Endpoint]" --output text 2>/dev/null || true
}

# invoke_task TASK: runs TASK of the maintenance routine synchronously and
# prints its result. Fails when the function returns an error.
invoke_task() {
  local task="$1" meta
  meta=$(aws lambda invoke --function-name "$ROUTINE" --cli-binary-format raw-in-base64-out \
    --payload "{\"task\":\"$task\"}" --query '[StatusCode,FunctionError]' --output text \
    "$WORK_DIR/$task.json")
  note "  result: $(cat "$WORK_DIR/$task.json")"
  [[ "$meta" == 200*None* || "$meta" == "200" ]]
}

# api_post PATH: POSTs the JSON read from stdin to the API through its domain
# and prints the HTTP status (the body, tokens included, is discarded).
api_post() {
  curl -s -o /dev/null -w '%{http_code}' -X POST "https://$API_DOMAIN/v1$1" \
    -H 'Content-Type: application/json' --data-binary @- || true
}

TOTAL_STAGES=7

banner "PlantAí · After the first deploy: alerts and production e-mail"

# ── 1. Tools, account and stack ──────────────────────────────────────────
stage "Tools, AWS account and the stack"
say "Checking the tools, the signed-in account and whether the stack $STACK is up"
say "(scripts/aws-first-deploy-wizard.sh comes before this one)."
printf '\n'
require_tools aws curl
require_aws_identity
STATUS=$(stack_status)
if [[ "$STATUS" != CREATE_COMPLETE && "$STATUS" != UPDATE_COMPLETE ]]; then
  warn "the stack $STACK is $STATUS. Run scripts/aws-first-deploy-wizard.sh first"
  note "(or wait for the running deploy to finish)."
  exit 1
fi
API_FUNCTION=$(stack_resource AWS::Lambda::Function ApiFunction)
ROUTINE=$(stack_resource AWS::Lambda::Function MaintenanceRoutineFunction)
TOPIC_ARN=$(stack_resource AWS::SNS::Topic MaintenanceAlerts)
ROUTINE_LOGS=$(stack_resource AWS::Logs::LogGroup MaintenanceRoutineLogs)
API_LOGS=$(stack_resource AWS::Logs::LogGroup ApiLogs)
if [[ -z "$API_FUNCTION" || -z "$ROUTINE" || -z "$TOPIC_ARN" ]]; then
  warn "could not find the API function, the routine function or the alerts topic in the stack."
  exit 1
fi
printf '  %s✓ stack%s %s: %s\n' "$GREEN" "$RESET" "$STACK" "$STATUS"
note "  API      $API_FUNCTION"
note "  routine  $ROUTINE"
note "  topic    $TOPIC_ARN"
printf '\n'
confirm "Is this the AWS account the API lives in?" || { say "Switch AWS_PROFILE and run again."; exit 1; }

# ── 2. SNS e-mail subscription ───────────────────────────────────────────
stage "E-mail subscription of the alerts (SNS)"
say "The alerts (a routine failure, Neon above 80 CU-hours) only arrive once the"
say "ALERT_EMAIL address confirms the topic subscription."
printf '\n'
SUBSCRIPTION=$(subscription_state "$TOPIC_ARN")
SUBSCRIPTION_ARN=${SUBSCRIPTION%%[[:space:]]*}
ALERT_EMAIL=${SUBSCRIPTION##*[[:space:]]}
if [[ "$SUBSCRIPTION_ARN" == arn:* ]]; then
  printf '  %s✓ already confirmed%s %s\n' "$GREEN" "$RESET" "$ALERT_EMAIL"
else
  if [[ "$SUBSCRIPTION_ARN" == PendingConfirmation ]]; then
    warn "the subscription of $ALERT_EMAIL is not confirmed yet."
  else
    warn "the topic has no e-mail subscription (AWS deletes unconfirmed ones after a few days)."
    ALERT_EMAIL=""
    ask_email ALERT_EMAIL "E-mail address that receives the alerts (the same as the GitHub secret ALERT_EMAIL):"
  fi
  step "Look in $ALERT_EMAIL (and in spam) for 'AWS Notification - Subscription Confirmation'"
  note "  and click 'Confirm subscription'."
  if confirm "Could not find the e-mail, or the link expired? Ask AWS for a new one"; then
    aws sns subscribe --topic-arn "$TOPIC_ARN" --protocol email \
      --notification-endpoint "$ALERT_EMAIL" >/dev/null
    printf '  %s✓ requested%s check the inbox again.\n' "$GREEN" "$RESET"
  fi
  while true; do
    SUBSCRIPTION_ARN=$(subscription_state "$TOPIC_ARN")
    SUBSCRIPTION_ARN=${SUBSCRIPTION_ARN%%[[:space:]]*}
    [[ "$SUBSCRIPTION_ARN" == arn:* ]] && break
    printf '\r  %swaiting for the confirmation (every 15 s)...%s   ' "$DIM" "$RESET"
    sleep 15
  done
  printf '\r\033[K  %s✓ confirmed%s %s\n' "$GREEN" "$RESET" "$ALERT_EMAIL"
fi
printf '\n'
if confirm "Send a test message through the topic, to see an alert arrive?"; then
  # The alert e-mails are for Ângelo, in Portuguese like the real ones.
  aws sns publish --topic-arn "$TOPIC_ARN" --subject "PlantAi: teste dos alertas" \
    --message "Teste do scripts/aws-after-first-deploy-wizard.sh. Se chegou, os alertas chegam." >/dev/null
  printf '  %s✓ published%s it should reach %s in a moment.\n' "$GREEN" "$RESET" "$ALERT_EMAIL"
  pause "Press Enter once it arrived (or to go on)"
fi
printf '\n'
pause "Press Enter to continue"

# ── 3. Maintenance routine, by hand ──────────────────────────────────────
stage "Maintenance routine: both tasks by hand"
say "Running now the two tasks the EventBridge Scheduler calls by itself:"
say "ping-database (every Monday, 9:00) and check-neon-usage (every day, 8:00)."
note "A failure here sets off the alarm, and the error e-mail reaches ALERT_EMAIL."
printf '\n'
ROUTINE_OK=true
for task in ping-database check-neon-usage; do
  step "$task"
  if invoke_task "$task"; then
    printf '  %s✓ no error%s\n' "$GREEN" "$RESET"
  else
    printf '  %s✗ failed%s %s\n' "$RED" "$RESET" "$task"
    ROUTINE_OK=false
  fi
done
if [[ "$ROUTINE_OK" != true ]]; then
  printf '\n'
  say "Last lines of the routine's log ($ROUTINE_LOGS):"
  aws logs tail "$ROUTINE_LOGS" --since 10m --format short 2>/dev/null | tail -n 20 | sed 's/^/    /' || true
  note "Missing NEON_API_KEY/NEON_PROJECT_ID or a refused key: run"
  note "scripts/aws-first-deploy-wizard.sh again (stage 4 replaces the values; that is where the Neon"
  note "key is rotated), then this one. New parameters apply from the next cold start."
  exit 1
fi
note "alerted:false is expected while the month is below 80 CU-hours."
printf '\n'
pause "Press Enter to continue"

# ── 4. Resend domain ─────────────────────────────────────────────────────
stage "Resend: domain $ZONE (records on the send. subdomain)"
say "To leave test mode, Resend needs the domain verified: DKIM on"
say "resend._domainkey and SPF/return path (MX and TXT) on the send. subdomain, in Registro.br's DNS."
printf '\n'
DKIM=$(dns_records "resend._domainkey.$ZONE" TXT)
SEND_MX=$(dns_records "send.$ZONE" MX)
SEND_TXT=$(dns_records "send.$ZONE" TXT)
if [[ "$DKIM" == *p=* && -n "$SEND_MX" && "$SEND_TXT" == *v=spf1* ]]; then
  printf '  %s✓ already in DNS%s DKIM, MX and SPF of send.%s\n' "$GREEN" "$RESET" "$ZONE"
else
  open_url "https://resend.com/domains"
  step "Resend → Domains → Add Domain → name $ZONE, region North Virginia (us-east-1) → Add."
  note "  (if the domain is already there, just open it.) Resend shows 3 records, all with"
  note "  names relative to $ZONE: a TXT resend._domainkey, an MX send and a TXT send."
  pause "Press Enter when you see the records"
  open_url "https://registro.br/painel/"
  step "Registro.br panel → domain $ZONE → DNS → 'Editar zona' → one 'Nova entrada' for each:"
  printf '\n    %sTXT%s  Nome resend._domainkey   Dados: the p=... value Resend shows\n' "$BOLD" "$RESET"
  printf '    %sMX%s   Nome send                Dados: feedback-smtp.<region>.amazonses.com, priority 10\n' "$BOLD" "$RESET"
  printf '    %sTXT%s  Nome send                Dados: v=spf1 include:amazonses.com ~all\n\n' "$BOLD" "$RESET"
  note "  Copy the values from Resend (they win over the ones above), without quotes → 'Salvar'."
  note "  Do not touch the certificate's validation CNAME nor the one of $API_DOMAIN."
  pause "Press Enter once they are saved"
  while true; do
    DKIM=$(dns_records "resend._domainkey.$ZONE" TXT)
    SEND_MX=$(dns_records "send.$ZONE" MX)
    SEND_TXT=$(dns_records "send.$ZONE" TXT)
    [[ "$DKIM" == *p=* && -n "$SEND_MX" && "$SEND_TXT" == *v=spf1* ]] && break
    printf '\r  %sDNS: DKIM %s · MX %s · SPF %s (every 30 s)%s   ' "$DIM" \
      "$([[ "$DKIM" == *p=* ]] && echo ok || echo not-yet)" \
      "$([[ -n "$SEND_MX" ]] && echo ok || echo not-yet)" \
      "$([[ "$SEND_TXT" == *v=spf1* ]] && echo ok || echo not-yet)" "$RESET"
    sleep 30
  done
  printf '\r\033[K  %s✓ in DNS%s DKIM, MX and SPF of send.%s\n' "$GREEN" "$RESET" "$ZONE"
fi
note "  MX send.$ZONE: $(tr '\n' ' ' <<<"$SEND_MX")"
printf '\n'
open_url "https://resend.com/domains"
step "In Resend, open $ZONE → Verify DNS Records (or wait: it checks by itself)."
note "  The three records and the domain must become 'Verified' (minutes, sometimes more)."
until confirm "Does the domain $ZONE show as Verified in Resend?"; do
  note "Wait a bit and check again. A 'Failed' record is usually a value pasted with quotes"
  note "or with the domain repeated in the name (send.$ZONE.$ZONE)."
done
printf '\n'
pause "Press Enter to continue"

# ── 5. RESEND_API_KEY and EMAIL_FROM in SSM ──────────────────────────────
stage "SSM: production RESEND_API_KEY and EMAIL_FROM"
say "Without RESEND_API_KEY the API only writes the e-mails to the log; with the domain"
say "verified, the sender becomes $EMAIL_FROM_PRODUCTION."
printf '\n'
CHANGED=false
if ssm_exists RESEND_API_KEY; then
  printf '  %s✓ already exists%s RESEND_API_KEY\n' "$GREEN" "$RESET"
  note "  If it is 'Full access' or not restricted to the domain, replace it with a new one."
fi
if ! ssm_exists RESEND_API_KEY || confirm "Replace RESEND_API_KEY?"; then
  open_url "https://resend.com/api-keys"
  step "Resend → API Keys → Create API key → name plantai-production,"
  note "  Permission 'Sending access', Domain $ZONE → Add → copy it (shown only once)."
  RESEND_KEY=""
  while true; do
    ask_secret RESEND_KEY "RESEND_API_KEY (hidden):"
    if [[ "$RESEND_KEY" != re_* ]]; then
      warn "Resend keys start with re_; again."
    elif ssm_put RESEND_API_KEY "$RESEND_KEY"; then
      break
    fi
  done
  RESEND_KEY=""
  CHANGED=true
fi
CURRENT_FROM=$(aws ssm get-parameter --name "$SSM_PREFIX/EMAIL_FROM" --with-decryption \
  --query Parameter.Value --output text 2>/dev/null || true)
if [[ "$CURRENT_FROM" == "$EMAIL_FROM_PRODUCTION" ]]; then
  printf '  %s✓ already done%s EMAIL_FROM = %s\n' "$GREEN" "$RESET" "$CURRENT_FROM"
else
  note "  EMAIL_FROM now: ${CURRENT_FROM:-(does not exist)}"
  if confirm "Switch EMAIL_FROM to $EMAIL_FROM_PRODUCTION?"; then
    ssm_put EMAIL_FROM "$EMAIL_FROM_PRODUCTION"
    CHANGED=true
  else
    warn "without the switch, the e-mails stay in Resend's test mode."
  fi
fi
printf '\n'
pause "Press Enter to continue"

# ── 6. Cold start of the API ─────────────────────────────────────────────
stage "Cold start of the API, to read the SSM again"
say "The function reads the SSM only at cold start: instances already warm keep the"
say "old sender. A change to the function's configuration replaces every instance."
printf '\n'
if [[ "$CHANGED" == true ]] || confirm "Nothing changed in the SSM now. Force a cold start anyway?"; then
  DESCRIPTION=$(aws lambda get-function-configuration --function-name "$API_FUNCTION" \
    --query Description --output text)
  step "Changing the function's description, then restoring the original (same as the stack's template)."
  aws lambda update-function-configuration --function-name "$API_FUNCTION" \
    --description "$DESCRIPTION (reload $(date -u +%Y-%m-%dT%H:%M:%SZ))" >/dev/null
  aws lambda wait function-updated-v2 --function-name "$API_FUNCTION"
  aws lambda update-function-configuration --function-name "$API_FUNCTION" \
    --description "$DESCRIPTION" >/dev/null
  aws lambda wait function-updated-v2 --function-name "$API_FUNCTION"
  printf '  %s✓ function updated%s the next requests start cold.\n' "$GREEN" "$RESET"
fi
CODE=$(curl -s -o /dev/null -w '%{http_code}' "https://$API_DOMAIN/v1/health" || true)
if [[ "$CODE" == 200 ]]; then
  printf '  %s✓ GET https://%s/v1/health → 200%s\n' "$GREEN" "$API_DOMAIN" "$RESET"
else
  warn "GET /v1/health → $CODE. Last lines of the API's log ($API_LOGS):"
  aws logs tail "$API_LOGS" --since 10m --format short 2>/dev/null | tail -n 20 | sed 's/^/    /' || true
  exit 1
fi
printf '\n'
pause "Press Enter to continue"

# ── 7. A real sign-up ────────────────────────────────────────────────────
stage "Test sign-up: does the code arrive from nao-responda@$ZONE?"
say "A real sign-up on the production API (POST /v1/auth/signup, the app's own"
say "call). Use an address of yours; the account is real, in the production database."
note "If the address already has a confirmed account, the 'you already have an account' notice arrives, from the same sender."
printf '\n'
SIGNUP_EMAIL=""
ask_email SIGNUP_EMAIL "Sign-up e-mail address:"
SIGNUP_PASSWORD=""
while (( ${#SIGNUP_PASSWORD} < 8 )); do
  ask_secret SIGNUP_PASSWORD "Account password (8 or more characters, hidden):"
done
EMAIL_JSON=$(json_string "$SIGNUP_EMAIL") || exit 1
PASSWORD_JSON=$(json_string "$SIGNUP_PASSWORD") || exit 1
SIGNUP_PASSWORD=""
CODE=$(printf '{"name":"Ângelo","email":%s,"password":%s}' "$EMAIL_JSON" "$PASSWORD_JSON" \
  | api_post /auth/signup)
PASSWORD_JSON=""
if [[ "$CODE" != 202 ]]; then
  warn "POST /v1/auth/signup → $CODE (429 = the limit of 3 e-mails in 15 minutes for that address)."
  exit 1
fi
printf '  %s✓ 202%s sign-up accepted, e-mail on its way to %s\n\n' "$GREEN" "$RESET" "$SIGNUP_EMAIL"
step "Open the inbox: the sender should be $EMAIL_FROM_PRODUCTION."
if ! confirm "Did it come from nao-responda@$ZONE?"; then
  say "API log lines about e-mail in the last 10 minutes ($API_LOGS):"
  aws logs tail "$API_LOGS" --since 10m --format short 2>/dev/null \
    | grep -iE 'resend|e-?mail|not sent' | tail -n 20 | sed 's/^/    /' || true
  note "'Not sent (no RESEND_API_KEY)' = the function did not read the key: run this wizard again."
  note "A Resend error about the domain = go back to stage 4. Check spam too."
  exit 1
fi
printf '\n'
SIGNUP_CODE=""
ask SIGNUP_CODE "6-digit code, to confirm the account (Enter skips):"
if [[ "$SIGNUP_CODE" =~ ^[0-9]{6}$ ]]; then
  CODE=$(printf '{"email":%s,"code":"%s"}' "$EMAIL_JSON" "$SIGNUP_CODE" | api_post /auth/verify-email)
  if [[ "$CODE" == 200 ]]; then
    printf '  %s✓ account confirmed%s sign in to the app with that e-mail and password.\n' "$GREEN" "$RESET"
  else
    warn "POST /v1/auth/verify-email → $CODE; confirm it in the app, with the code from the e-mail."
  fi
fi
printf '\n'
note "Done: alerts confirmed, routine running and e-mails sent from $EMAIL_FROM_PRODUCTION."
note "To rotate the Neon key or another secret: scripts/aws-first-deploy-wizard.sh (stage 4),"
note "then stage 6 of this one (cold start) or a deploy."
pause "Press Enter for the summary"

finish
